  v <- as.vector(v)
  if (is.logical(v)) {
    ifelse(is.na(v), "NA", ifelse(v, "T", "F"))
  } else if (is.integer(v)) {
    ifelse(is.na(v), "NA", as.character(v))
  } else {
    ifelse(is.na(v), "NA", sprintf("%.17g", v))
  }
}

one <- function() matrixStats::allValue(as.vector(x))
ans <- one()
writeLines(encode(ans), "/tmp/ms-proof-allValue-ans.txt")

lx <- matrix(c(TRUE, NA, FALSE, TRUE, NA, FALSE, TRUE, FALSE, NA), nrow = 3)
writeLines(encode(matrixStats::allValue(as.vector(lx))), "/tmp/ms-proof-allValue-lx.txt")

elapsed <- numeric(20)
for (i in seq_len(20)) {
  t0 <- as.numeric(Sys.time())
  one()
  elapsed[[i]] <- as.numeric(Sys.time()) - t0
}
cat(median(elapsed) * 1000, "\n")

